package golang

import (
	"bytes"
	"fmt"
	"go/format"
	"strings"

	"github.com/leroux/charter/internal/record"
)

// GoVersion is the go line of the generated module's go.mod: the oldest Go
// the generated file builds with.
const GoVersion = "1.21"

// Generate renders the claims module: its go.mod, which requires nothing,
// and specs.go, declaring a symbol per entry and per observation, the
// types they hold, and the Verifies and Observes a test calls. regen is
// the command named in the file's header.
//
//charter:realizes CH-020
func Generate(rec *record.Record, module, regen string) (gomod, specs []byte, err error) {
	gomod = []byte(fmt.Sprintf("// Code generated by %s. DO NOT EDIT.\n\nmodule %s\n\ngo %s\n", regen, module, GoVersion))
	var b bytes.Buffer
	fmt.Fprintf(&b, "// Code generated from %s by %s. DO NOT EDIT.\n\n", rec.Dir, regen)
	b.WriteString("// Package claims is the charter's record as Go: a symbol per entry and per\n// observation, and the Verifies and Observes a test opens with.\npackage claims\n\n")
	b.WriteString(marker)
	for _, e := range rec.Entries {
		fmt.Fprintf(&b, "\n// %s is %s: %s\n", e.Symbol, e.ID, oneLine(e.Title))
		if e.Status == "deprecated" {
			fmt.Fprintf(&b, "//\n// Deprecated: %s is retired; see its Changes in %s. Add no new anchors.\n", e.ID, e.File)
		}
		fmt.Fprintf(&b, "var %s = &Spec{ID: %q, Title: %q, Status: %s", e.Symbol, e.ID, e.Title, statusName(e.Status))
		if e.Kind != "" {
			fmt.Fprintf(&b, ", Kind: %q", e.Kind)
		}
		b.WriteString("}\n")
	}
	for _, o := range rec.Observations {
		fmt.Fprintf(&b, "\n// %s is an observation of %s: %s\nvar %s = &Observation{Name: %q, Subject: %q, Status: %q}\n", o.Name, o.Subject, oneLine(o.Text), o.Name, o.Name, o.Subject, o.Status)
	}
	specs, err = format.Source(b.Bytes())
	if err != nil {
		return nil, nil, fmt.Errorf("the generated specs.go does not parse: %w", err)
	}
	return gomod, specs, nil
}

func statusName(s string) string {
	switch s {
	case "planned":
		return "Planned"
	case "deprecated":
		return "Deprecated"
	}
	return "Active"
}

// oneLine is text as one comment line, a comment closer escaped.
func oneLine(s string) string {
	return strings.ReplaceAll(strings.Join(strings.Fields(s), " "), "*/", "*\\/")
}

// marker is the generated package's own code: the types its symbols hold,
// and Verifies and Observes, which append one JSON line per citation and
// the test's outcome to the file CHARTER_EVENTS names once the test ends.
//
//charter:realizes CH-024
const marker = `import (
	"encoding/json"
	"os"
	"runtime"
	"sync"
	"testing"
)

// Status is an entry's status.
type Status string

// The statuses an entry may have.
const (
	Planned    Status = "planned"
	Active     Status = "active"
	Deprecated Status = "deprecated"
)

// Spec is an entry of the record: a need or a decision.
type Spec struct {
	ID, Title string
	Status    Status
	Kind      string
}

// Observation is a fact about a system the code does not own.
type Observation struct {
	Name, Subject, Status string
}

// Verifies opens a test that verifies an entry, naming by handle the
// scenarios it exercises. With CHARTER_EVENTS set, the test's outcome is
// recorded for each citation once it ends.
func Verifies(tb testing.TB, spec *Spec, handles ...string) {
	tb.Helper()
	if spec == nil {
		tb.Fatal("claims: Verifies needs a spec")
		return
	}
	record(tb, spec.ID, handles)
}

// Observes opens a probe that checks an observation against the live
// system.
func Observes(tb testing.TB, o *Observation) {
	tb.Helper()
	if o == nil {
		tb.Fatal("claims: Observes needs an observation")
		return
	}
	record(tb, o.Name, nil)
}

// event is one line of the events file.
type event struct {
	ID      string ` + "`json:\"id\"`" + `
	Handle  string ` + "`json:\"handle,omitempty\"`" + `
	Test    string ` + "`json:\"test\"`" + `
	File    string ` + "`json:\"file\"`" + `
	Outcome string ` + "`json:\"outcome\"`" + `
}

var eventsMu sync.Mutex

func record(tb testing.TB, id string, handles []string) {
	path := os.Getenv("CHARTER_EVENTS")
	if path == "" {
		return
	}
	_, file, _, _ := runtime.Caller(2)
	if len(handles) == 0 {
		handles = []string{""}
	}
	tb.Cleanup(func() {
		outcome := "passed"
		switch {
		case tb.Failed():
			outcome = "failed"
		case tb.Skipped():
			outcome = "skipped"
		}
		eventsMu.Lock()
		defer eventsMu.Unlock()
		f, err := os.OpenFile(path, os.O_APPEND|os.O_CREATE|os.O_WRONLY, 0o644)
		if err != nil {
			tb.Errorf("claims: the events file: %v", err)
			return
		}
		defer f.Close()
		for _, h := range handles {
			line, _ := json.Marshal(event{ID: id, Handle: h, Test: tb.Name(), File: file, Outcome: outcome})
			// One write per line, opened to append: a line is never split
			// by another process's.
			if _, err := f.Write(append(line, '\n')); err != nil {
				tb.Errorf("claims: the events file: %v", err)
			}
		}
	})
}
`
